<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once dirname(__DIR__).'/classes/GreenPortalDatabase.php';require_once dirname(__DIR__).'/classes/UsuarioSessao.php';
if(empty($_SESSION['autenticado'])||empty($_SESSION['tenant']['banco_dados'])){http_response_code(401);exit('Sessão expirada.');}$pdo=GreenPortalDatabase::connect(GreenPortalDatabase::env(),(string)$_SESSION['tenant']['banco_dados'],'GPT');if(!UsuarioSessao::atualizar($pdo,$_SESSION)){http_response_code(401);exit('Sessão expirada.');}
$uid=(int)($_SESSION['usuario']['codusuario']??0);$unit=max(0,(int)($_GET['codunidade']??$_POST['codunidade']??0));$aspect=max(0,(int)($_GET['codaspecto']??$_POST['codaspecto']??0));$impact=max(0,(int)($_GET['codimpacto']??$_POST['codimpacto']??0));$csrf=(string)($_SESSION['controle_documentos_links_csrf']??'');if($csrf===''){$csrf=bin2hex(random_bytes(24));$_SESSION['controle_documentos_links_csrf']=$csrf;}
$clean=static function(mixed $v):string{$v=trim((string)$v);if($v===''||in_array(strtolower($v),['null','^null','\\null'],true))return '';for($i=0;$i<2;$i++){$d=html_entity_decode($v,ENT_QUOTES|ENT_HTML5,'UTF-8');if($d===$v)break;$v=$d;}return $v;};$e=static fn(mixed $v):string=>htmlspecialchars($clean($v),ENT_QUOTES,'UTF-8');$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Token de segurança inválido.');$doc=max(0,(int)($_POST['coddocumento']??0));if($doc<1||$unit<1||($aspect<1&&$impact<1))throw new RuntimeException('Contexto do controle inválido.');$rt=$aspect>0?'lais_documentosxaspectos':'lais_documentosximpactos';$rc=$aspect>0?'CODASPECTOSOCIAL':'CODIMPACTOSOCIAL';$rv=$aspect>0?$aspect:$impact;$check=$pdo->prepare("SELECT COUNT(*) FROM `$rt` WHERE CODDOCUMENTO=? AND `$rc`=? AND codunidade=?");$check->execute([$doc,$rv,$unit]);$exists=(int)$check->fetchColumn()>0;
if(!$exists){$q=$pdo->prepare("INSERT INTO `$rt` (CODDOCUMENTO,`$rc`,codunidade) VALUES (?,?,?)");$q->execute([$doc,$rv,$unit]);$q=$pdo->prepare('SELECT coddocumento FROM content_documents WHERE chave_idempotencia=?');$q->execute(['CONTROLE_DOCUMENTO_'.$doc]);$content=(int)$q->fetchColumn();if(!$content){$q=$pdo->prepare("INSERT INTO content_documents(chave_idempotencia,codigo,titulo,descricao,tipo_documento,codusuario_criador,codunidade,origem_entidade,origem_id,status) SELECT ?,CONCAT('CONTROLE_DOCUMENTO_',CODDOCUMENTO),COALESCE(NULLIF(TITULO,''),CONCAT('Documento de controle ',CODDOCUMENTO)),NULLIF(ARQUIVO,''),'CONTROLE',?,?,'documentos',CAST(CODDOCUMENTO AS CHAR),'RASCUNHO' FROM documentos WHERE CODDOCUMENTO=?");$q->execute(['CONTROLE_DOCUMENTO_'.$doc,$uid,$unit,$doc]);$content=(int)$pdo->lastInsertId();}$type=$aspect>0?'CONTROLE_LAIS_ASPECTO':'CONTROLE_LAIS_IMPACTO';$q=$pdo->prepare("INSERT IGNORE INTO content_document_links(coddocumento,tipo_entidade,entidade_id,codunidade,papel,origem_vinculo,status,codusuario) VALUES(?,?,?,?,'EVIDENCIA','USUARIO','ATIVO',?)");$q->execute([$content,$type,$rv,$unit,$uid]);$message='Documento vinculado ao contexto.';}else{$q=$pdo->prepare("DELETE FROM `$rt` WHERE CODDOCUMENTO=? AND `$rc`=? AND codunidade=?");$q->execute([$doc,$rv,$unit]);$type=$aspect>0?'CONTROLE_LAIS_ASPECTO':'CONTROLE_LAIS_IMPACTO';$q=$pdo->prepare('DELETE FROM content_document_links WHERE coddocumento=(SELECT coddocumento FROM content_documents WHERE chave_idempotencia=?) AND tipo_entidade=? AND entidade_id=? AND codunidade=?');$q->execute(['CONTROLE_DOCUMENTO_'.$doc,$type,$rv,$unit]);$message='Vínculo removido. O documento não foi excluído.';}}catch(Throwable $x){$error=$x->getMessage();}
$rt=$aspect>0?'lais_documentosxaspectos':'lais_documentosximpactos';$rc=$aspect>0?'CODASPECTOSOCIAL':'CODIMPACTOSOCIAL';$rv=$aspect>0?$aspect:$impact;$q=$pdo->prepare("SELECT d.CODDOCUMENTO,d.CODIGO,d.TITULO,d.ARQUIVO,CASE WHEN r.CODDOCUMENTO IS NULL THEN 0 ELSE 1 END vinculado FROM documentos d LEFT JOIN `$rt` r ON r.CODDOCUMENTO=d.CODDOCUMENTO AND r.`$rc`=? AND r.codunidade=? ORDER BY d.TITULO,d.CODDOCUMENTO");$q->execute([$rv,$unit]);$docs=$q->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/font/bootstrap-icons.min.css?v=2"><style>body{margin:0;padding:14px;background:var(--gp-surface);color:var(--gp-text);font:13px Arial,sans-serif}.head{display:flex;justify-content:space-between;align-items:center}.table{background:#fff}.muted{color:var(--gp-muted)}</style><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body><main><div class="head mb-2"><div><h5 class="mb-1"><i class="bi bi-link-45deg me-1"></i>Vínculos de documentos</h5><div class="small muted">Selecione documentos existentes para este contexto. Remover o vínculo não exclui o arquivo.</div></div><span class="badge text-bg-light"><?=count(array_filter($docs,fn($d)=>(int)$d['vinculado']===1))?> vinculados</span></div><?php if($message):?><div class="alert alert-success py-2"><?=$e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger py-2"><?=$e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=$e($csrf)?>"><input type="hidden" name="codunidade" value="<?=$unit?>"><input type="hidden" name="codaspecto" value="<?=$aspect?>"><input type="hidden" name="codimpacto" value="<?=$impact?>"><div class="table-responsive border rounded"><table class="table table-sm table-hover align-middle mb-0"><thead class="table-light"><tr><th></th><th>Código</th><th>Título</th><th>Arquivo</th><th>Status</th></tr></thead><tbody><?php foreach($docs as $d):?><tr><td><button class="btn btn-sm <?=$d['vinculado']?'btn-outline-danger':'btn-outline-success'?>" name="coddocumento" value="<?=$e($d['CODDOCUMENTO'])?>" title="<?=$d['vinculado']?'Remover vínculo':'Vincular documento'?>"><i class="bi <?=$d['vinculado']?'bi-link-45deg':'bi-plus-lg'?>"></i></button></td><td><?=$e($d['CODIGO'])?></td><td><?=$e($d['TITULO'])?></td><td><?=($file=$clean($d['ARQUIVO']))!==''?$e($file):'—'?></td><td><?php if($d['vinculado']):?><span class="badge text-bg-success">Vinculado</span><?php else:?><span class="badge text-bg-light">Disponível</span><?php endif;?></td></tr><?php endforeach;if(!$docs):?><tr><td colspan="5" class="text-center muted py-4">Nenhum documento disponível.</td></tr><?php endif;?></tbody></table></div></form></main></body></html>
